const content = $('Gemini — Generate Post').item.json.text;
const keyword = $('Get Next Keyword').item.json.Keyword;
const rowId = $('Get Next Keyword').item.json.row_number;

// Cover image per keyword — relevant Unsplash photos
const coverImages = {
  'n8n blog automation': 'photo-1517694712202-14dd9538aa97',
  'claude ai writing workflow': 'photo-1677442135703-1787eea5ce01',
  'n8n vs zapier 2026': 'photo-1551288049-bebda4e38f71',
  'n8n content automation': 'photo-1518770660439-4636190af475',
  'claude api n8n': 'photo-1555066931-4365d14bab8c',
  'claude vs chatgpt automation': 'photo-1620712943543-bcc4688e7485',
  'claude ai mistakes': 'photo-1516116216624-53e697fedbea',
  'ai output accuracy 2026': 'photo-1551288049-bebda4e38f71',
  'gemini 1.5 flash review': 'photo-1620712943543-bcc4688e7485',
  'n8n review 2026': 'photo-1451187580459-43490279c0fa',
  'ai blog make money 2026': 'photo-1579621970563-ebec7560ff3e',
  'make money with n8n': 'photo-1579621970563-ebec7560ff3e',
  'passive income ai content': 'photo-1460925895917-afdab827c52f',
  'ai blog affiliate marketing': 'photo-1460925895917-afdab827c52f',
  'micro saas with ai 2026': 'photo-1551288049-bebda4e38f71',
  'ai replacing human judgment': 'photo-1507003211169-0a1dd7228f2d',
  'human in the loop ai': 'photo-1552664730-d307ca884978',
  'using claude daily': 'photo-1677442135703-1787eea5ce01',
  'chatgpt dependency': 'photo-1620712943543-bcc4688e7485',
  'ai productivity mindset': 'photo-1499750310107-5fef28a66643'
};

const photoId = coverImages[keyword.toLowerCase()] || 'photo-1677442135703-1787eea5ce01';
const coverImageUrl = `https://images.unsplash.com/${photoId}?w=800&h=450&fit=crop`;

// Extract title from frontmatter
const titleMatch = content.match(/title: ['"](.+?)['"]/i);
const title = titleMatch ? titleMatch[1] : 'New Post';

// Generate slug from keyword (reliable)
const slug = keyword
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .trim();

// Replace coverImage in frontmatter with keyword-specific Unsplash photo
let fixedContent = content.replace(
  /coverImage: ['"]https?:\/\/[^'"\n]+['"]/,
  `coverImage: "${coverImageUrl}"`
);

return {
  content: fixedContent,
  title: title,
  slug: slug,
  filename: `${slug}.mdx`,
  keyword: keyword,
  rowId: rowId,
  publishDate: new Date().toISOString().split('T')[0]
};
